SEC={s['name']:i for i,s in enumerate(CS)}
def sl(sec,a,b): return [t[0] for t in CS[SEC[sec]]['tasks'][a:b]]
ID={t:i for s in CS for i,t in s['tasks']}
def C(*names): return [ID[n] for n in names]
def R(t,u): return (t,u)

