# cf=(lo,hi,tags). flt=(title,tags,lo,hi,target). ac=(lo,hi) on the AtCoder Problems difficulty scale.
# pat: (pattern, problems that cover it). Filled a month ahead; a gap gets one problem rated 1600 or below.
# gap: ('cf', contest, index) or ('lc', slug, title), placed on the week's Wednesday.
def W(name,stage,cf,flt,ac,cses=(),rd=(),note='',pat=(),gap=()):
    return dict(name=name,stage=stage,cf=cf,flt=flt,ac=ac,cses=list(cses),rd=list(rd),note=note,pat=list(pat),gap=list(gap))

